import{_ as t,o,c as r,a2 as l}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"狼族","description":"","frontmatter":{},"headers":[],"relativePath":"表层/种族/狼族.md","filePath":"表层/种族/狼族.md","lastUpdated":null}'),e={name:"表层/种族/狼族.md"};function i(n,a,s,u,h,q){return o(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="狼族" tabindex="-1">狼族 <a class="header-anchor" href="#狼族" aria-label="Permalink to &quot;狼族&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>狼族是该世界中极具特殊性的种族。黑暗时代中，狼族在全大陆范围内被公认为奴隶种族，遭受极度压迫。黑暗时代后期，一位觉醒的狼族少年改变了种族的命运，狼族随之经历了一段令大陆记忆深刻的动荡岁月，又在此后逐步转型。当前狼族建立独立国家——狼国，正处于国力上升期，在鹿国与熊国的冷战对峙中执行平衡策略，是具备硬实力的&quot;危险平衡者&quot;。</p><hr><h2 id="体貌特征" tabindex="-1">体貌特征 <a class="header-anchor" href="#体貌特征" aria-label="Permalink to &quot;体貌特征&quot;">​</a></h2><ul><li><strong>形态</strong>：直立行走，有狼耳与狼尾，嘴部向前突出，但不多。</li><li><strong>体型</strong>：中等体型，适合多种环境生存与作战。</li><li><strong>毛色</strong>：以灰、黑、黄、白色为主，纯色种较为稀少，偶有其余色彩变种个体。</li></ul><hr><h2 id="种族特质" tabindex="-1">种族特质 <a class="header-anchor" href="#种族特质" aria-label="Permalink to &quot;种族特质&quot;">​</a></h2><p>狼族在公众认知中天生具备<strong>天真纯善</strong>的性格特征：</p><ul><li>易于相信他人言论。</li><li>极易被洗脑驯化，经过简单训练后便会转变为反抗意识薄弱的顺从个体。</li></ul><p>这一特质使狼族在全大陆范围内被视为&quot;天生的奴隶&quot;，也是其在黑暗时代遭受系统性压迫的根源。</p><hr><h2 id="历史" tabindex="-1">历史 <a class="header-anchor" href="#历史" aria-label="Permalink to &quot;历史&quot;">​</a></h2><h3 id="黑暗时代-奴隶种族" tabindex="-1">黑暗时代：奴隶种族 <a class="header-anchor" href="#黑暗时代-奴隶种族" aria-label="Permalink to &quot;黑暗时代：奴隶种族&quot;">​</a></h3><p>黑暗时代开始后，狼族成为被系统性压迫的奴隶种族：</p><ul><li><strong>&quot;天生的奴隶&quot;</strong>：被公认为天生适合为奴的种族，完全不具备基本权利，遭受极度压迫。</li><li><strong>&quot;狼圈&quot;</strong>：其余种族大肆建立专门繁育狼族的设施——&quot;狼圈&quot;，将狼族大规模繁育作为奴隶来源。因狼族只需简单洗脑即可成为上好奴隶，奴役成本极低。</li><li><strong>针对性繁育</strong>：系统性的大规模繁育使狼族人口维持在一定规模，但完全处于被奴役状态。</li></ul><h3 id="狼灾时期" tabindex="-1">狼灾时期 <a class="header-anchor" href="#狼灾时期" aria-label="Permalink to &quot;狼灾时期&quot;">​</a></h3><p>黑暗时代后期，一位被南方狼村收养的狼族少年在压迫中觉醒，以<strong>民族复仇</strong>为核心率领狼族崛起，独立建国。这位少年以<strong>复仇之力</strong>（民间亦有&quot;狼魔法&quot;&quot;邪法&quot;等称呼）独自巡游大地四方，数年内灭绝猪、虎、豹、蝠四族，最终在即将灭绝鹰族时忽然消失。</p><p>觉醒者活跃的这段时期，狼族的旗帜为<strong>黑色打底 + 红色圆环</strong>，意识形态<strong>极端排外</strong>，主张&quot;唯狼族论&quot;，被视为全大陆的头号大敌。其余种族将这段岁月称为**&quot;狼灾时期&quot;**——其极端排外与复仇行径给大陆留下了流传至今的恐怖记忆。</p><h3 id="觉醒者消失后的转型" tabindex="-1">觉醒者消失后的转型 <a class="header-anchor" href="#觉醒者消失后的转型" aria-label="Permalink to &quot;觉醒者消失后的转型&quot;">​</a></h3><p>觉醒者消失后，狼族经历了深刻的意识形态转型：</p><ul><li><strong>旗帜变化</strong>：旗帜逐渐变为<strong>金黄色系配色 + 圆环标识</strong>。</li><li><strong>意识形态演变</strong>：从&quot;主动侵略&quot;逐步转变为&quot;人不犯我我不犯人，你若惹我便彻底歼灭&quot;，其后随着新一代成长，进一步演变为<strong>和平主义甚至极端亲外主义</strong>，仅保留国家独立，不再主动挑起冲突。</li></ul><blockquote><p>待定：传闻在那位觉醒的狼族少年消失之后、狼族走向和平之前，曾有一位被称为&quot;小狼&quot;的领袖扭转了族群的走向，相关事迹尚未有完整记载。</p></blockquote><h3 id="老一辈与新一代的割裂" tabindex="-1">老一辈与新一代的割裂 <a class="header-anchor" href="#老一辈与新一代的割裂" aria-label="Permalink to &quot;老一辈与新一代的割裂&quot;">​</a></h3><blockquote><p>故老传闻：狼族内部存在观念差异明显的两代群体——某座边远小城仍悬挂着旧日的红黑旗帜，聚居着不少老一辈的战士，与主流的新一代狼族在思维方式上差异显著。该传闻未经证实。</p></blockquote><h3 id="军备发展" tabindex="-1">军备发展 <a class="header-anchor" href="#军备发展" aria-label="Permalink to &quot;军备发展&quot;">​</a></h3><p>狮族战争让狼族彻底&quot;醒悟&quot;。战后狼族不再依赖超自然力量的老本，转而紧跟时代，<strong>积极发展热武器与核武器，扩张军备</strong>，成为鹿熊冷战中具备硬实力的&quot;危险平衡者&quot;。</p><hr><h2 id="现状" tabindex="-1">现状 <a class="header-anchor" href="#现状" aria-label="Permalink to &quot;现状&quot;">​</a></h2><p>黑暗时代结束后，狼族建立了独立国家——<strong>狼国</strong>：</p><ul><li><strong>地缘地位</strong>：作为新兴国家，正处于国力上升期，在鹿国与熊国的冷战对峙中处于关键位置，成为双方争夺与扶持的焦点。</li><li><strong>外交策略</strong>：狼国领导层在大国夹缝中执行危险的平衡策略，既不倒向任何一方，又同时从双方获取利益。</li><li><strong>军备</strong>：经过狮族战争后的军备扩张，狼国已成为冷战中具备硬实力的&quot;危险平衡者&quot;。</li></ul><p>此外，黑暗时代结束后，狐族在狼族庇佑下建立城邦，主要依附于狼族生存。</p><hr><h2 id="深层真相" tabindex="-1">深层真相 <a class="header-anchor" href="#深层真相" aria-label="Permalink to &quot;深层真相&quot;">​</a></h2><blockquote><p>狼族&quot;天真纯善&quot;特质的真实成因、觉醒者消失的缘由等不属表层认知。</p></blockquote><ul><li><a href="./../../中层/世界/神机谋划" class="layer-link" data-layer="中层">神机谋划</a> —— 狼族特质的真相</li><li><a href="./../../中层/人物/狼族少年" class="layer-link" data-layer="中层">狼族少年</a> —— 那位觉醒的狼族少年</li><li><a href="./../../中层/历史/正传历史" class="layer-link" data-layer="中层">正传历史</a> —— 黑暗时代真实进程</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./../历史/黑暗时代">黑暗时代</a></li><li><a href="./../历史/当前时代">当前时代</a></li><li><a href="./狐族">狐族</a></li><li><a href="./兔族">兔族</a></li></ul><hr>',39)])])}const g=t(e,[["render",i]]);export{c as __pageData,g as default};
